```ts
// onError is typed against Error, so a rejection that is not one is wrapped rather than dropped; the rethrow above stays the caller's original value.
function asError(rejection: unknown): Error {
  if (rejection instanceof Error) return rejection;
  if (typeof rejection === 'string') return new Error(rejection, {cause: rejection});
  return new Error(`non-error rejection: ${describeRejection(rejection)}`, {cause: rejection});
}

// JSON.stringify returns undefined on its own input and throws on a cycle, so the probe keeps the wrap itself from throwing.
function stringifyRejection(rejection: unknown): string | undefined {
  try {
    return JSON.stringify(rejection);
  } catch {
    return undefined;
  }
}

function describeRejection(rejection: unknown): string {
  return stringifyRejection(rejection) ?? String(rejection);
}
```

