    it('calls onError with an Error that carries the thrown object as cause when the stream rejects with a plain object', async () => {
      const reason = {code: 503, detail: 'upstream down'};
      const callOrder: string[] = [];
      let seenError: Error | undefined;
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          callOrder.push('onError');
          seenError = error;
        },
        afterSession: async () => void callOrder.push('afterSession'),
      };

      const orchestrator = createChatOrchestrator(createErrorProvider(reason), promptBuilder, undefined, {hooks});
      const outcome = await orchestrator.processMessage(createSession('hello')).then(
        value => ({rejected: false, reason: value as unknown}),
        (thrown: unknown) => ({rejected: true, reason: thrown})
      );

      expect({
        outcome,
        callOrder,
        isError: seenError instanceof Error,
        causeIsThrown: seenError?.cause === reason,
        hasMessage: typeof seenError?.message === 'string' && seenError.message.length > 0,
      }).toEqual({
        outcome: {rejected: true, reason},
        callOrder: ['onError', 'afterSession'],
